grader.tests:
a={'x':('a',3),'y':('b',None),'z':('c',4)}
assert live(a,3)=={'y':('b',None),'z':('c',4)}
assert len(a)==3
assert live({},0)=={}
assert live(a,2)==a
assert live(a,2) is not a

a={'db':{'port':1,'hosts':['a']},'x':3}
b={'db':{'port':2},'x':None}
r=merge(a,b)
assert r=={'db':{'port':2,'hosts':['a']},'x':None}
r['db']['hosts'].append('z')
assert a['db']['hosts']==['a']
assert b=={'db':{'port':2},'x':None}
assert merge({'a':[1]},{'a':[2]})=={'a':[2]}

assert normalize('/a//b/../c/.')=='/a/c'
assert normalize('/../../')=='/'
assert normalize('/a/.../')=='/a/...'
for p in ['', 'a/b']:
    try: normalize(p)
    except ValueError: pass
    else: raise AssertionError('relative accepted')

a={'a':1,'b':2,'d':None}; b={'a':1,'b':3,'c':4}
assert reconcile(a,b)=={'create':['d'],'update':['b'],'delete':['c']}
assert a=={'a':1,'b':2,'d':None}
assert reconcile({},{})=={'create':[],'update':[],'delete':[]}

a={'a':1,'b':2,'d':None}; b={'a':1,'b':3,'c':4}
assert reconcile(a,b)=={'create':['d'],'update':['b'],'delete':['c']}
assert a=={'a':1,'b':2,'d':None}
assert reconcile({},{})=={'create':[],'update':[],'delete':[]}

assert normalize('/a//b/../c/.')=='/a/c'
assert normalize('/../../')=='/'
assert normalize('/a/.../')=='/a/...'
for p in ['', 'a/b']:
    try: normalize(p)
    except ValueError: pass
    else: raise AssertionError('relative accepted')

a={'x':('a',3),'y':('b',None),'z':('c',4)}
assert live(a,3)=={'y':('b',None),'z':('c',4)}
assert len(a)==3
assert live({},0)=={}
assert live(a,2)==a
assert live(a,2) is not a

a={'db':{'port':1,'hosts':['a']},'x':3}
b={'db':{'port':2},'x':None}
r=merge(a,b)
assert r=={'db':{'port':2,'hosts':['a']},'x':None}
r['db']['hosts'].append('z')
assert a['db']['hosts']==['a']
assert b=={'db':{'port':2},'x':None}
assert merge({'a':[1]},{'a':[2]})=={'a':[2]}
